def write_batch(ids, label):
    assert set(ids) <= set(P.keys()), f"{label}: missing preds for {set(ids)-set(P.keys())}"
    n = 0
    for cid in ids:
        d = P[cid]
        out = {"case_id": cid, "prediction_text": d["prediction_text"], "basis": d["basis"],
               "confidence": d["confidence"], "trigger": d["trigger"]}
        with open(os.path.join(PRED_DIR, cid + ".json"), "w", encoding="utf-8") as f:
            json.dump(out, f, ensure_ascii=False, indent=1)
        n += 1
    print(f"{label}: wrote {n}")
    return n

total = write_batch(B13, "B13") + write_batch(B14, "B14")
# verify each written file by exact open
trig = {"changed_main": 0, "reserve_used": 0, "disputed": 0}
for cid in B13 + B14:
    with open(os.path.join(PRED_DIR, cid + ".json"), encoding="utf-8") as f:
        d = json.load(f)
    assert d["case_id"] == cid and set(d.keys()) == {"case_id","prediction_text","basis","confidence","trigger"}
    assert set(d["trigger"].keys()) == {"changed_main","reserve_used","disputed","reason"}
    for k in trig:
        trig[k] += 1 if d["trigger"][k] else 0
print("total", total, "trigger_counts", trig)
